        'bio': 'Born in Patan.',
        'languages': ['Nepali', 'English'],
        'verified': true,
        'cities': ['Lalitpur'],
      },
    });

    expect(e.id, 7);
    expect(e.slug, 'newari-food-walk');
    expect(e.title, 'Newari Food Walk');
    expect(e.price, 45);
    expect(e.rating, 4.8);
