{"kind":"tool","id":"YWpf9wx_Iq8","toolName":"write_file","input":{"path":"mobile/test/city_update_test.dart","instructions":"Add a focused mobile test file for the CityUpdate model and the city updates provider.","content":"import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:guides_nepal/shared/models/city_update.dart';

import 'package:guides_nepal/features/experiences/experience_repository.dart';

/// Local, file-backed tests for the traveller-facing guide-updates feed.
/// No HTTP client is ever constructed — parsing and the provider contract are
/// checked against the JSON shape returned by `GET /updates`.
void main() {
  group('CityUpdate.fromJson', () {
    test('parses a full capacity update', () {
      final update = CityUpdate.fromJson({
        'id': 7,
        'update_type': 'capacity',
        'message': 'Two spots left on the Saturday sunrise hike.',
        'guide_name': 'Pemba Sherpa',
        'area': 'Everest Base Camp',
        'event_date': '2026-11-14T00:00:00',
        'current_capacity': 6,
        'max_capacity': 8,
        'created_at': '2026-10-20T09:30:00',
        'listing_title': 'Sunrise over Kala Patthar',
        'cities': ['Lukla', 'Namche Bazaar'],
      });

      expect(update.id, 7);
      expect(update.updateType, 'capacity');
      expect(update.guideName, 'Pemba Sherpa');
      expect(update.area, 'Everest Base Camp');
      expect(update.currentCapacity, 6);
      expect(update.maxCapacity, 8);
      expect(update.listingTitle, 'Sunrise over Kala Patthar');
      expect(update.cities, ['Lukla', 'Namche Bazaar']);
      expect(update.typeLabel, 'Capacity');
      expect(update.capacityLabel, '6/8 spots');
      expect(update.eventDate, isNotNull);
      expect(update.createdAt, isNotNull);
    });

    test('tolerates a sparse announcement', () {
      final update = CityUpdate.fromJson({
        'id': 1,
        'update_type': 'announcement',
        'message': 'Trail to the monastery is closed for repairs.',
        'guide_name': 'Mingma G.',
        'cities': ['Pokhara'],
      });

      expect(update.id, 1);
      expect(update.guideName, 'Mingma G.');
      expect(update.area, isNull);
      expect(update.eventDate, isNull);
      expect(update.createdAt, isNull);
      expect(update.currentCapacity, isNull);
      expect(update.maxCapacity, isNull);
      expect(update.cities, ['Pokhara']);
      expect(update.capacityLabel, isNull);
      // `announcement` and an empty both-caps case title-cased once only.
      expect(update.typeLabel, 'Announcement');
    });

    test('never invents a guide name or silently drops text', () {
      final anonymous = CityUpdate.fromJson(const {});
      expect(anonymous.guideName, 'A local guide');
      expect(anonymous.message, '');
      expect(anonymous.typeLabel, 'Update');
      expect(anonymous.cities, isEmpty);
      // A single-sided capacity pair still says what it knows.
      expect(
        CityUpdate.fromJson(const {
          'max_capacity': 12,
        }).capacityLabel,
        'Up to 12 spots',
      );
      expect(
        CityUpdate.fromJson(const {
          'current_capacity': 4,
        }).capacityLabel,
        '4 spots taken',
      );
    });

    test('keeps only public update types in the documented allow-list', () {
      // Bookings are a guide's own workflow and must never reach travellers;
      // the public list is the contract shared with
      // `backend/app/api/v1/public.py`.
      expect(
        CityUpdate.publicTypes,
        ['announcement', 'availability', 'capacity', 'schedule'],
      );
      expect(CityUpdate.publicTypes, isNot(contains('booking')));
    });

    test('a non-list cities value is ignored rather than crashing', () {
      final update =
          CityUpdate.fromJson(const {'cities': 'not-a-list'});
      expect(update.cities, isEmpty);
    });
  });

  group('cityUpdatesProvider', () {
    test('is keyed by city and auto-disposed', () {
      final container = ProviderContainer();
      addTearDown(container.dispose);
      expect(
        cityUpdatesProvider('Pokhara').toString(),
        contains('Pokhara'),
      );
      expect(
        cityUpdatesProvider('Pokhara').toString(),
        isNot(cityUpdatesProvider('Kathmandu').toString()),
      );
    });
  });
}"}}
