{"kind":"tool","id":"jp7SUg7W26k","toolName":"write_file","input":{"path":"mobile/lib/features/profile/profile_draft.dart","instructions":"Add a testable draft that owns profile edit validation.","content":"import '../../l10n/app_strings.dart';
import '../../shared/models/app_user.dart';

/// Editable state of the signed-in traveler's profile.
///
/// Kept apart from the screen so the rules can be tested as rules. The server's
/// `ProfileUpdate` schema takes all of these as optional strings with no
/// validation of its own, so the app is where a blank name or a 4 000-character
/// bio has to be caught — and where the limits have to be honest about being
/// ours, not the server's.
class ProfileDraft {
  const ProfileDraft({
    this.firstName = '',
    this.lastName = '',
    this.phone = '',
    this.bio = '',
  });

  /// Practical caps for a phone form: long enough for an international
  /// number written with spaces, short enough to fit one line everywhere.
  static const int nameMaxLength = 60;
  static const int phoneMaxLength = 20;
  static const int bioMaxLength = 300;

  final String firstName;
  final String lastName;
  final String phone;
  final String bio;

  factory ProfileDraft.fromUser(AppUser user) => ProfileDraft(
        firstName: user.firstName ?? '',
        lastName: user.lastName ?? '',
        phone: user.phone ?? '',
        bio: user.bio ?? '',
      );

  ProfileDraft copyWith({
    String? firstName,
    String? lastName,
    String? phone,
    String? bio,
  }) =>
      ProfileDraft(
        firstName: firstName ?? this.firstName,
        lastName: lastName ?? this.lastName,
        phone: phone ?? this.phone,
        bio: bio ?? this.bio,
      );

  /// Field-keyed messages, empty when the draft may be sent.
  Map<String, String> validate() {
    final errors = <String, String>{};
    final first = firstName.trim();
    final last = lastName.trim();

    if (first.isEmpty && last.isEmpty) {
      errors['firstName'] = AppStrings.nameRequired;
    }
    if (first.length > nameMaxLength) {
      errors['firstName'] = AppStrings.fieldTooLong;
    }
    if (last.length > nameMaxLength) {
      errors['lastName'] = AppStrings.fieldTooLong;
    }

    final trimmedPhone = phone.trim();
    if (trimmedPhone.isNotEmpty) {
      final allowed = RegExp(r'^[0-9+\-() ]+$');
      if (!allowed.hasMatch(trimmedPhone) ||
          trimmedPhone.length > phoneMaxLength) {
        errors['phone'] = AppStrings.phoneInvalid;
      }
    }

    if (bio.trim().length > bioMaxLength) {
      errors['bio'] = AppStrings.fieldTooLong;
    }
    return errors;
  }

  bool get isValid => validate().isEmpty;

  /// Only the editable fields, trimmed. Empty phone/bio are sent as empty
  /// strings so clearing a field in the app clears it on the server.
  Map<String, dynamic> toJson() => {
        'firstName': firstName.trim(),
        'lastName': lastName.trim(),
        'phone': phone.trim(),
        'bio': bio.trim(),
      };
}
"}}


{"kind":"tool","id":"jp8c7Zs9TBU","toolName":"write_file","input":{"path":"mobile/lib/features/profile/profile_edit_screen.dart","instructions":"Add the profile editing screen with photo upload.","content":"import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:image_picker/image_picker.dart';

import '../../app/theme/app_colors.dart';
import '../../app/theme/app_spacing.dart';
import '../../app/theme/app_typography.dart';
import '../../core/config/app_config.dart';
import '../../core/network/api_exception.dart';
import '../../l10n/app_strings.dart';
import '../../shared/widgets/widgets.dart';
import '../auth/auth_repository.dart';
import 'profile_draft.dart';

/// Edits the signed-in traveler's name, photo and contact details.
///
/// The server stores these through `PATCH /profile/me` and
/// `POST /profile/photos/upload`; nothing here can change email, password or
/// role, because nothing here is allowed to. Saving puts the server's
/// refreshed identity straight into the session, so the Profile tab updates
/// without a second fetch.
class ProfileEditScreen extends ConsumerStatefulWidget {
  const ProfileEditScreen({super.key});

  @override
  ConsumerState<ProfileEditScreen> createState() => _ProfileEditScreenState();
}

class _ProfileEditScreenState extends ConsumerState<ProfileEditScreen> {
  /// The server's upload cap (`backend/app/core/storage.py`).
  static const int _maxPhotoBytes = 5 * 1024 * 1024;

  final _picker = ImagePicker();
  final _formKey = GlobalKey<FormState>();
  late final TextEditingController _firstName;
  late final TextEditingController _lastName;
  late final TextEditingController _phone;
  late final TextEditingController _bio;

  List<int>? _pickedBytes;
  String? _pickedName;
  String? _pickedType;
  bool _saving = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    final user = ref.read(authControllerProvider).user;
    final draft = user == null ? const ProfileDraft() : ProfileDraft.fromUser(user);
    _firstName = TextEditingController(text: draft.firstName);
    _lastName = TextEditingController(text: draft.lastName);
    _phone = TextEditingController(text: draft.phone);
    _bio = TextEditingController(text: draft.bio);
  }

  @override
  void dispose() {
    _firstName.dispose();
    _lastName.dispose();
    _phone.dispose();
    _bio.dispose();
    super.dispose();
  }

  ProfileDraft get _draft => ProfileDraft(
        firstName: _firstName.text,
        lastName: _lastName.text,
        phone: _phone.text,
        bio: _bio.text,
      );

  Future<void> _pickPhoto() async {
    if (_saving) return;
    try {
      final file = await _picker.pickImage(
        source: ImageSource.gallery,
        // A portrait is shown at 58 dp; 1200 px is generous and keeps uploads
        // well inside the server's 5 MB ceiling on a phone camera.
        maxWidth: 1200,
        imageQuality: 85,
      );
      if (file == null) return;
      final bytes = await file.readAsBytes();
      if (!mounted) return;
      if (bytes.length > _maxPhotoBytes) {
        setState(() => _error = AppStrings.photoTooLarge);
        return;
      }
      setState(() {
        _pickedBytes = bytes;
        _pickedName = file.name.isEmpty ? 'avatar.jpg' : file.name;
        _pickedType = _detectType(file.mimeType, _pickedName!);
        _error = null;
      });
    } catch (_) {
      if (mounted) {
        setState(() => _error = 'Could not open your photos.');
      }
    }
  }

  /// The server accepts JPEG, PNG and WebP and checks the bytes, so the type
  /// travels with the upload rather than being guessed from the extension.
  String _detectType(String? mime, String name) {
    if (mime != null && mime.startsWith('image/')) return mime;
    final lower = name.toLowerCase();
    if (lower.endsWith('.png')) return 'image/png';
    if (lower.endsWith('.webp')) return 'image/webp';
    return 'image/jpeg';
  }

  Future<void> _save() async {
    if (_saving) return;
    final draft = _draft;
    final errors = draft.validate();
    if (errors.isNotEmpty) {
      // Surface through the form so the offending field carries its message.
      _formKey.currentState?.validate();
      setState(() => _error = null);
      return;
    }

    setState(() {
      _saving = true;
      _error = null;
    });

    final controller = ref.read(authControllerProvider.notifier);
    var photoFailed = false;
    try {
      final payload = draft.toJson();
      await controller.updateProfile(
        firstName: payload['firstName'] as String,
        lastName: payload['lastName'] as String,
        phone: payload['phone'] as String,
        bio: payload['bio'] as String,
      );

      final bytes = _pickedBytes;
      if (bytes != null) {
        try {
          final url = await controller.uploadAvatar(
            bytes: bytes,
            filename: _pickedName ?? 'avatar.jpg',
            contentType: _pickedType ?? 'image/jpeg',
          );
          // Second PATCH: the photo only becomes visible once its path is
          // stored on the user row.
          await controller.updateProfile(avatarUrl: url);
        } on ApiException {
          photoFailed = true;
        }
      }
    } on ApiException catch (e) {
      if (!mounted) return;
      setState(() {
        _saving = false;
        _error = e.message;
      });
      return;
    }

    if (!mounted) return;
    setState(() => _saving = false);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          photoFailed
              ? 'Profile saved, but the photo could not be uploaded.'
              : AppStrings.profileSaved,
        ),
      ),
    );
    Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    final auth = ref.watch(authControllerProvider);
    final user = auth.user;
    final avatarUrl = user?.avatarUrl;

    return Scaffold(
      backgroundColor: AppColors.background,
      appBar: AppBar(
        backgroundColor: AppColors.background,
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        leading: IconButton(
          tooltip: AppStrings.back,
          icon: const Icon(Icons.arrow_back_ios_new_rounded, size: 20),
          onPressed: _saving ? null : () => Navigator.of(context).maybePop(),
        ),
        title: Text(AppStrings.editProfile, style: AppTypography.h3),
        centerTitle: false,
      ),
      body: SafeArea(
        top: false,
        child: ListView(
          padding: const EdgeInsets.fromLTRB(
            AppSpacing.gutter,
            AppSpacing.x2,
            AppSpacing.gutter,
            AppSpacing.x10,
